-- Extends five existing documentation pages with the features added since they were written:
-- Boxes (strict and dynamic pages, sections and devices, managing boxes), Caching (the page cache in detail),
-- Languages (addresses, links, statistics), Templates (layout variables), API (hiding articles, address restriction, change feed, images, statistics, presets).
-- Each section is appended once: a statement runs only while its heading is missing, so the migration is safe to rerun.
SET NAMES utf8mb4;

UPDATE cms_articles SET bodytext = CONCAT(bodytext, '\n\n## Strict and dynamic pages\n\nEvery page is either strict or dynamic (the `strict` field of the page).\n\n- A **strict** page answers only its own address. `/docs/` is valid and `/docs/anything/` is a 404.\n- A **dynamic** page answers its own address and everything after it. The page that is found is still `/addons/`, and the rest of the address, for example `v21-2` and `server-1` in `/addons/v21-2/server-1/`, is passed to the box as parameters. The box reads them with `$this->getUrlParams()` and works with them.\n\nFor a dynamic page the framework cannot know which parameters are valid, so the box decides. A box that does not accept an address, for example a third parameter that does not exist in `/addons/v21-2/server-1/xyz/`, throws `\\Wbengine\\Exception\\RuntimeException` with the code `404`, and the framework shows the 404 page. Without that, every address under the page would show the page. A dynamic page is listed in the sitemap by its own address only (see [Search engines](/docs/seo/)).')
WHERE id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/boxes/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND LOCATE('## Strict and dynamic pages', bodytext) = 0;

UPDATE cms_article_translations SET bodytext = CONCAT(bodytext, '\n\n## Striktní a dynamické stránky\n\nKaždá stránka je buď striktní, nebo dynamická (pole `strict` stránky).\n\n- **Striktní** stránka odpovídá jen na vlastní adresu. `/docs/` je platná a `/docs/cokoli/` je 404.\n- **Dynamická** stránka odpovídá na vlastní adresu i na vše za ní. Nalezená stránka je stále `/addons/` a zbytek adresy, například `v21-2` a `server-1` v `/addons/v21-2/server-1/`, se předá boxu jako parametry. Box je čte přes `$this->getUrlParams()` a pracuje s nimi.\n\nU dynamické stránky framework nemůže vědět, které parametry jsou platné, takže rozhoduje box. Box, který adresu nepřijímá, například třetí parametr, který v `/addons/v21-2/server-1/xyz/` neexistuje, vyhodí `\\Wbengine\\Exception\\RuntimeException` s kódem `404` a framework zobrazí stránku 404. Bez toho by každá adresa pod stránkou zobrazila stránku. Dynamická stránka je v sitemapě uvedena jen vlastní adresou (viz [Vyhledávače](/cs/docs/seo/)).')
WHERE article_id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/boxes/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND locale = 'cs' AND LOCATE('## Striktní a dynamické stránky', bodytext) = 0;

UPDATE cms_articles SET bodytext = CONCAT(bodytext, '\n\n## Sections, order and devices\n\nA box belongs to a section of the layout and to the pages that show it (the `sites` of the box), and boxes of a section are shown in their `order`. A box is hidden from a page by taking the page off its list; the box itself stays.\n\nA box can be limited to devices with `device_min` and `device_strict`. The device classes are 1 mobile, 2 tablet and 3 desktop. `device_min` 0 means any device. Otherwise the device must be at least `device_min`, and with `device_strict` it must be exactly `device_min`. The stored default (`device_min` 1, not strict) shows the box on every device. The page cache keeps one copy of a page per device class, so a device limit never shows a visitor a copy made for another class (see [Caching](/docs/caching/)).')
WHERE id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/boxes/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND LOCATE('## Sections, order and devices', bodytext) = 0;

UPDATE cms_article_translations SET bodytext = CONCAT(bodytext, '\n\n## Sekce, pořadí a zařízení\n\nBox patří do sekce layoutu a ke stránkám, které ho zobrazují (pole `sites` boxu), a boxy sekce se zobrazují podle svého pořadí (`order`). Box se ze stránky skryje tím, že se stránka odebere z jeho seznamu; box sám zůstává.\n\nBox lze omezit na zařízení pomocí `device_min` a `device_strict`. Třídy zařízení jsou 1 mobil, 2 tablet a 3 stolní počítač. `device_min` 0 znamená jakékoli zařízení. Jinak musí být zařízení alespoň `device_min` a s `device_strict` přesně `device_min`. Uložená výchozí hodnota (`device_min` 1, ne striktní) zobrazí box na každém zařízení. Cache stránek drží jednu kopii stránky pro každou třídu zařízení, takže omezení podle zařízení nikdy neukáže návštěvníkovi kopii vytvořenou pro jinou třídu (viz [Cache](/cs/docs/caching/)).')
WHERE article_id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/boxes/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND locale = 'cs' AND LOCATE('## Sekce, pořadí a zařízení', bodytext) = 0;

UPDATE cms_articles SET bodytext = CONCAT(bodytext, '\n\n## Managing boxes without code\n\nBoxes of a registered type can be added and changed through API v2 and by the assistant of the [MCP server](/docs/mcp/): list the box types and boxes, add a box to a section, change its order and device limit, take it off a page and put it back. A type is registered by the application in `Application::registerBoxTypes()` with its module, method and the sections it may be placed in. A type that shows the article of its page is marked, so a client knows that a page with such a box is not empty. See [API](/docs/rest-api/).')
WHERE id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/boxes/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND LOCATE('## Managing boxes without code', bodytext) = 0;

UPDATE cms_article_translations SET bodytext = CONCAT(bodytext, '\n\n## Správa boxů bez kódu\n\nBoxy registrovaného typu lze přidávat a měnit přes API v2 a asistentem [MCP serveru](/cs/docs/mcp/): vypsat typy boxů a boxy, přidat box do sekce, změnit jeho pořadí a omezení zařízení, sundat ho ze stránky a vrátit. Typ registruje aplikace v `Application::registerBoxTypes()` s jeho modulem, metodou a sekcemi, kam smí. Typ, který zobrazuje článek své stránky, je označen, takže klient ví, že stránka s takovým boxem není prázdná. Viz [API](/cs/docs/rest-api/).')
WHERE article_id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/boxes/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND locale = 'cs' AND LOCATE('## Správa boxů bez kódu', bodytext) = 0;

UPDATE cms_articles SET bodytext = CONCAT(bodytext, '\n\n## The page cache in detail\n\nThe page cache serves a stored copy of a page to anonymous visitors before any box runs. The copy is kept per path, per language and per device class (mobile, tablet, desktop). A response that is private, sets a cookie or depends on the visitor is never stored, and neither is a page requested by a logged-in user, an error page or a response that a custom route produced. A page that is served from the cache carries the header `X-WBengine-Cache: HIT`.\n\n`/robots.txt` and `/sitemap.xml` are generated for every request and are not stored in the page cache, so a page that was just published is in the sitemap at once.\n\nThe statistics still count a page that is served from the cache, in the language of the cached page. A change to a page reaches visitors after the cache lifetime (`cache.pages.ttl`, 60 seconds by default) or after a flush. See the [settings reference](/docs/settings/) for the keys, `allowPaths` and `denyPaths`.')
WHERE id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/caching/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND LOCATE('## The page cache in detail', bodytext) = 0;

UPDATE cms_article_translations SET bodytext = CONCAT(bodytext, '\n\n## Cache stránek podrobně\n\nCache stránek podává anonymním návštěvníkům uloženou kopii stránky dřív, než se spustí jakýkoli box. Kopie se drží pro každou cestu, jazyk a třídu zařízení (mobil, tablet, stolní počítač). Odpověď, která je soukromá, nastavuje cookie nebo závisí na návštěvníkovi, se neukládá nikdy, stejně jako stránka vyžádaná přihlášeným uživatelem, chybová stránka nebo odpověď vlastní cesty. Stránka podaná z cache nese hlavičku `X-WBengine-Cache: HIT`.\n\n`/robots.txt` a `/sitemap.xml` se generují při každém požadavku a do cache stránek se neukládají, takže právě zveřejněná stránka je v sitemapě hned.\n\nStatistiky počítají i stránku podanou z cache, v jazyce uložené stránky. Změna stránky se k návštěvníkům dostane po uplynutí životnosti cache (`cache.pages.ttl`, výchozí 60 sekund) nebo po vyprázdnění. Klíče, `allowPaths` a `denyPaths` viz [přehled nastavení](/cs/docs/settings/).')
WHERE article_id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/caching/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND locale = 'cs' AND LOCATE('## Cache stránek podrobně', bodytext) = 0;

UPDATE cms_articles SET bodytext = CONCAT(bodytext, '\n\n## Addresses, links and statistics\n\nWith `urlPrefix` on, a language has its own address prefix: `/cs/blog/` is the Czech version of `/blog/`, and the default language has no prefix. The layout gets the variables `lang`, `locale`, `alternates` (the address of the current page in every language, for the language switcher) and `hreflangs` (the same as absolute addresses, with `x-default`). Every page also has one canonical link with the absolute address of the page in its own language. The sitemap lists each language of a page that has a translation, with links to the others. See [Search engines](/docs/seo/).\n\nPages, menu entries and articles are translated independently, and a page without a translation shows the default language. The API lists the languages that each page, menu entry and article has (`translation_locales`) and takes translations per language. The assistant of the [MCP server](/docs/mcp/) uses that to warn when a page, a menu entry or an article lacks a translation for a language of the site.\n\nThe statistics record the views of a page per language, and the totals are the sum of all languages (see [Statistics](/docs/analytics/)).')
WHERE id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/languages/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND LOCATE('## Addresses, links and statistics', bodytext) = 0;

UPDATE cms_article_translations SET bodytext = CONCAT(bodytext, '\n\n## Adresy, odkazy a statistiky\n\nSe zapnutým `urlPrefix` má jazyk vlastní prefix adresy: `/cs/blog/` je česká verze `/blog/` a výchozí jazyk prefix nemá. Layout dostane proměnné `lang`, `locale`, `alternates` (adresa aktuální stránky v každém jazyce, pro přepínač jazyků) a `hreflangs` (totéž jako absolutní adresy, s `x-default`). Každá stránka má také jeden odkaz canonical s absolutní adresou stránky ve vlastním jazyce. Sitemapa uvádí každý jazyk stránky, která má překlad, s odkazy na ostatní. Viz [Vyhledávače](/cs/docs/seo/).\n\nStránky, položky menu a články se překládají nezávisle a stránka bez překladu zobrazí výchozí jazyk. API vypisuje jazyky, které každá stránka, položka menu a článek mají (`translation_locales`), a bere překlady po jazycích. Asistent [MCP serveru](/cs/docs/mcp/) podle toho upozorní, když stránce, položce menu nebo článku překlad některého jazyka webu chybí.\n\nStatistiky zaznamenávají zobrazení stránky po jazycích a součty jsou součtem všech jazyků (viz [Statistiky](/cs/docs/analytics/)).')
WHERE article_id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/languages/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND locale = 'cs' AND LOCATE('## Adresy, odkazy a statistiky', bodytext) = 0;

UPDATE cms_articles SET bodytext = CONCAT(bodytext, '\n\n## Layout variables\n\nThe layout `src/View/site.tpl` and the box templates can use these variables:\n\n| Variable | What it holds |\n|---|---|\n| `lang`, `locale` | the language of the request (`cs`) and its locale (`cs` or `pt_BR`) |\n| `meta.title`, `meta.description`, `meta.keywords` | the browser title, description and keywords of the page, in the language of the request |\n| `menu` | the menu entries of the site, translated per language |\n| `alternates` | the address of the current page in every language |\n| `hreflangs` | the same as absolute addresses, with `x-default`, for `hreflang` links |\n| `wbengine_version` | the version of the framework that renders the page, for example `6.7.0`, or `dev` when it is not a release |\n\nValues are escaped when printed, so `{$meta.title}` is safe. Text from the database that is trusted HTML is printed with `|raw`. The header of this site shows the version with `{$wbengine_version}`.')
WHERE id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/templates/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND LOCATE('## Layout variables', bodytext) = 0;

UPDATE cms_article_translations SET bodytext = CONCAT(bodytext, '\n\n## Proměnné layoutu\n\nLayout `src/View/site.tpl` a šablony boxů mohou používat tyto proměnné:\n\n| Proměnná | Co obsahuje |\n|---|---|\n| `lang`, `locale` | jazyk požadavku (`cs`) a jeho locale (`cs` nebo `pt_BR`) |\n| `meta.title`, `meta.description`, `meta.keywords` | titulek prohlížeče, popis a klíčová slova stránky v jazyce požadavku |\n| `menu` | položky menu webu, přeložené po jazycích |\n| `alternates` | adresa aktuální stránky v každém jazyce |\n| `hreflangs` | totéž jako absolutní adresy, s `x-default`, pro odkazy `hreflang` |\n| `wbengine_version` | verze frameworku, který stránku vykresluje, například `6.7.0`, nebo `dev`, když nejde o vydání |\n\nHodnoty se při výpisu escapují, takže `{$meta.title}` je bezpečné. Text z databáze, který je důvěryhodné HTML, se vypisuje přes `|raw`. Hlavička tohoto webu ukazuje verzi přes `{$wbengine_version}`.')
WHERE article_id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/templates/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND locale = 'cs' AND LOCATE('## Proměnné layoutu', bodytext) = 0;

UPDATE cms_articles SET bodytext = CONCAT(bodytext, '\n\n## Hiding and showing an article\n\n`POST /api/v2/articles/{id}/hide` hides a published article and `POST /api/v2/articles/{id}/unhide` shows it again. Both need the scopes `articles:write` and `publish:write` and the `If-Match` header with the ETag of the article, and both can be repeated safely. A hidden article is not displayed: its address answers 404, its menu entry disappears and it is left out of the sitemap. The list of articles can be filtered with `hidden=0` or `hidden=1`. The change is recorded in the change log as `hide` and `unhide`.')
WHERE id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/rest-api/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND LOCATE('## Hiding and showing an article', bodytext) = 0;

UPDATE cms_article_translations SET bodytext = CONCAT(bodytext, '\n\n## Skrytí a zobrazení článku\n\n`POST /api/v2/articles/{id}/hide` skryje zveřejněný článek a `POST /api/v2/articles/{id}/unhide` ho znovu zobrazí. Obě volání potřebují oprávnění `articles:write` a `publish:write` a hlavičku `If-Match` s ETagem článku a obě lze bezpečně opakovat. Skrytý článek se nezobrazuje: jeho adresa odpovídá 404, jeho položka menu zmizí a není v sitemapě. Seznam článků lze filtrovat přes `hidden=0` nebo `hidden=1`. Změna se zapíše do záznamu změn jako `hide` a `unhide`.')
WHERE article_id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/rest-api/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND locale = 'cs' AND LOCATE('## Skrytí a zobrazení článku', bodytext) = 0;

UPDATE cms_articles SET bodytext = CONCAT(bodytext, '\n\n## Limiting a key to addresses\n\nA key can be bound to IP addresses or CIDR ranges, on the issue form or later on the card of the key. Such a key works only from those addresses and any other request is refused with `ip_not_allowed`. The card of a key shows the address it was last used from, which helps to find a key that is used from an unexpected place.')
WHERE id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/rest-api/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND LOCATE('## Limiting a key to addresses', bodytext) = 0;

UPDATE cms_article_translations SET bodytext = CONCAT(bodytext, '\n\n## Omezení klíče na adresy\n\nKlíč lze vázat na IP adresy nebo rozsahy CIDR, ve formuláři při vydání nebo později na kartě klíče. Takový klíč funguje jen z těchto adres a každý jiný požadavek je odmítnut s `ip_not_allowed`. Karta klíče ukazuje adresu, ze které byl naposledy použit, což pomáhá najít klíč používaný z nečekaného místa.')
WHERE article_id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/rest-api/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND locale = 'cs' AND LOCATE('## Omezení klíče na adresy', bodytext) = 0;

UPDATE cms_articles SET bodytext = CONCAT(bodytext, '\n\n## The change feed and the history\n\n`GET /api/v2/changes` (scope `audit:read`) returns the change log, newest first, with these filters: `resource`, `resource_id`, `action`, `source`, `actor`, `since`, `until` and `outcome=rejected`, which lists the writes the site refused with their error code. Actor labels are written by the clients and are data, not proof of who someone is. The complete snapshots of a page, menu entry, section or box can be read, and restored, through its own `changes` path. See [Logging and audit](/docs/logging/).')
WHERE id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/rest-api/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND LOCATE('## The change feed and the history', bodytext) = 0;

UPDATE cms_article_translations SET bodytext = CONCAT(bodytext, '\n\n## Přehled změn a historie\n\n`GET /api/v2/changes` (oprávnění `audit:read`) vrací záznam změn od nejnovější s těmito filtry: `resource`, `resource_id`, `action`, `source`, `actor`, `since`, `until` a `outcome=rejected`, který vypíše zápisy, které web odmítl, s kódem chyby. Štítky aktérů zapisují klienti a jsou to data, ne důkaz, kdo je kdo. Úplné snímky stránky, položky menu, sekce nebo boxu lze číst a obnovit přes jeho vlastní cestu `changes`. Viz [Logování a audit](/cs/docs/logging/).')
WHERE article_id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/rest-api/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND locale = 'cs' AND LOCATE('## Přehled změn a historie', bodytext) = 0;

UPDATE cms_articles SET bodytext = CONCAT(bodytext, '\n\n## Images\n\n`POST /api/v2/images` uploads a PNG, JPEG or WebP image of at most 512 KiB as `base64` with its `mime` (scope `images:write`). The images can be listed and read, and deleted with the ETag and the write scope. The file needs a directory outside the web root (`apiV2.imageDirectory` or the environment variable `WBENGINE_IMAGE_DIR`); without it the site reports images as unavailable. The structure and the type of the file are checked, but this is not a full image decoder or an antivirus, so do not use it as a general file upload. An uploaded image is public media: it is served at its own address to anyone who has it, so it must not hold anything secret.')
WHERE id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/rest-api/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND LOCATE('## Images', bodytext) = 0;

UPDATE cms_article_translations SET bodytext = CONCAT(bodytext, '\n\n## Obrázky\n\n`POST /api/v2/images` nahraje obrázek PNG, JPEG nebo WebP do 512 KiB jako `base64` s jeho `mime` (oprávnění `images:write`). Obrázky lze vypsat, číst a smazat s ETagem a oprávněním k zápisu. Soubor potřebuje adresář mimo kořen webu (`apiV2.imageDirectory` nebo proměnná prostředí `WBENGINE_IMAGE_DIR`); bez něj web hlásí obrázky jako nedostupné. Kontroluje se struktura a typ souboru, ale není to plný dekodér obrázků ani antivirus, takže to nepoužívejte jako obecné nahrávání souborů. Nahraný obrázek je veřejné médium: na své adrese se podává každému, kdo ji zná, takže nesmí obsahovat nic tajného.')
WHERE article_id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/rest-api/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND locale = 'cs' AND LOCATE('## Obrázky', bodytext) = 0;

UPDATE cms_articles SET bodytext = CONCAT(bodytext, '\n\n## Statistics\n\n`GET /api/v2/analytics/overview` (scope `analytics:read`) takes `from` and `to` (`YYYY-MM-DD`), `granularity` (`day`, `week`, `month`) and an optional `locale`. It returns the totals, the series, the most viewed pages, articles and boxes, and the views by language. See [Statistics](/docs/analytics/).')
WHERE id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/rest-api/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND LOCATE('## Statistics', bodytext) = 0;

UPDATE cms_article_translations SET bodytext = CONCAT(bodytext, '\n\n## Statistiky\n\n`GET /api/v2/analytics/overview` (oprávnění `analytics:read`) bere `from` a `to` (`YYYY-MM-DD`), `granularity` (`day`, `week`, `month`) a volitelně `locale`. Vrací součty, řadu, nejzobrazovanější stránky, články a boxy a zobrazení po jazycích. Viz [Statistiky](/cs/docs/analytics/).')
WHERE article_id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/rest-api/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND locale = 'cs' AND LOCATE('## Statistiky', bodytext) = 0;

UPDATE cms_articles SET bodytext = CONCAT(bodytext, '\n\n## Presets and the MCP server\n\nWhen a key is issued the form offers presets for common uses: full management for the central Admin, an editor, an agent for content, an agent that writes drafts only, and read only. An AI assistant works through the [MCP server](/docs/mcp/) with such a key and can do only what the key allows.')
WHERE id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/rest-api/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND LOCATE('## Presets and the MCP server', bodytext) = 0;

UPDATE cms_article_translations SET bodytext = CONCAT(bodytext, '\n\n## Předvolby a MCP server\n\nPři vydání klíče formulář nabízí předvolby pro běžná použití: plnou správu pro centrální administraci, redaktora, agenta pro obsah, agenta, který píše jen koncepty, a jen čtení. AI asistent pracuje přes [MCP server](/cs/docs/mcp/) s takovým klíčem a smí jen to, co klíč dovoluje.')
WHERE article_id = (SELECT id FROM (SELECT id FROM cms_articles WHERE site_id = (SELECT site_id FROM cms_sites WHERE link = '/docs/rest-api/' ORDER BY site_id LIMIT 1) ORDER BY id LIMIT 1) AS a) AND locale = 'cs' AND LOCATE('## Předvolby a MCP server', bodytext) = 0;
